import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong(), m = nextLong();
        int k = nextInt();
        long[] fx = new long[k], fy = new long[k];
        for (int i = 0; i < k; i++) {
            fx[i] = nextLong();
            fy[i] = nextLong();
        }
        long radius = nextLong() * nextLong(), radius2 = radius * radius;
        // A lattice point is safe iff it lies strictly outside every fire's closed disk.
        long safe = 0;
        for (long x = 0; x <= n; x++)
            for (long y = 0; y <= m; y++) {
                boolean ok = true;
                for (int i = 0; i < k && ok; i++)
                    if ((x - fx[i]) * (x - fx[i]) + (y - fy[i]) * (y - fy[i]) <= radius2) ok = false;
                if (ok) safe++;
            }
        System.out.println(safe);
    }
}
